from PIL import Image
im=Image.open('chess_board.png').convert('RGB')
BGs=[(240,217,181),(181,136,99)]
def bgdist(p): return min(sum((p[i]-b[i])**2 for i in range(3)) for b in BGs)
def classify(p):
    if bgdist(p)<18**2: return ' '
    return '#' if sum(p)<400 else 'O'
occupied=[]
for r in range(8):
    for c in range(8):
        sq=im.crop((c*80,r*80,(c+1)*80,(r+1)*80))
        pts=[classify(sq.getpixel((x,y))) for y in range(80) for x in range(80)]
        if sum(ch!=' ' for ch in pts)>100:
            occupied.append((chr(ord('a')+c)+str(8-r),sq))
for name,sq in occupied:
    print('=== '+name+' ===')
    W,H=24,18
    for yy in range(H):
        line=''
        for xx in range(W):
            cnt={' ':0,'#':0,'O':0}
            for y in range(yy*80//H,(yy+1)*80//H):
                for x in range(xx*80//W,(xx+1)*80//W):
                    cnt[classify(sq.getpixel((x,y)))]+=1
            if cnt['#']>cnt['O'] and cnt['#']>2: ch='#'
            elif cnt['O']>cnt['#'] and cnt['O']>2: ch='O'
            else: ch=' '
            line+=ch
        print(line)
